import React, { useContext } from "react";
import "./CourseProjects.scss";
import { courseProjects } from "../../portfolio";
import { Fade } from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function CourseProjects() {
  const { isDark } = useContext(StyleContext);

  if (!courseProjects.display) {
    return null;
  }

  return (
    <div className="main" id="course-projects">
      <Fade bottom duration={1000} distance="20px">
        <h1 className="skills-heading">{courseProjects.title}</h1>
        <p className={isDark ? "dark-mode subTitle" : "subTitle"}>
          {courseProjects.subtitle}
        </p>

        <div className="course-list">
          {courseProjects.projects.map((project, i) => (
            <a
              key={i}
              href={project.pdf ? process.env.PUBLIC_URL + project.pdf.substring(1) : project.link || "#"}
              target="_blank"
              rel="noopener noreferrer"
              className={`course-list-item ${isDark ? "dark" : ""}`}
            >
              <span className={`course-list-category ${isDark ? "dark" : ""}`}>
                {project.category}
              </span>
              <span className={`course-list-title ${isDark ? "dark" : ""}`}>
                {project.title}
              </span>
              <span className={`course-list-desc ${isDark ? "dark" : ""}`}>
                {project.desc}
              </span>
              <span className="course-list-arrow">↗</span>
            </a>
          ))}
        </div>
      </Fade>
    </div>
  );
}
